components/Options.vuesrc/App.vue <pre><code>&lt;template&gt;
    &lt;div&gt;
        &lt;button @click="onUpdateCount"&gt;计数器{{ count }}&lt;/button&gt;
    &lt;/div&gt;
&lt;/template&gt;

&lt;script&gt;

export default {
    name: 'Options',
    data() {
        return {
            count: 0
        }
    },
    methods: {
        onUpdateCount() {
            this.count++
        }
    }
}
&lt;/script&gt;

