components/Syntax.vue <pre><code>&lt;template&gt;
   &lt;p&gt;{{age}}&lt;/p&gt;
   &lt;p v-if="age &gt;= 18"&gt;成年人&lt;/p&gt;
   &lt;p v-else-if="age &gt;= 0 &amp;&amp; age &lt; 18"&gt;未成年人&lt;/p&gt;
   &lt;!-- v-else 永远不能带条件，--&gt;
   &lt;p v-else&gt; {{age}} 非法年龄&lt;/p&gt;
   &lt;button @click="age++"&gt;年龄+&lt;/button&gt;
   &lt;button @click="age--"&gt;年龄-&lt;/button&gt;
&lt;/template&gt;

&lt;script setup&gt;
import { ref } from 'vue';
const age=ref(17)


