components/Syntax.vue <pre><code>&lt;template&gt;
   &lt;h1 v-show="ok"&gt;Hello!&lt;/h1&gt;
   &lt;button @click="ok = !ok"&gt;Toggler&lt;/button&gt;
&lt;/template&gt;

&lt;script setup&gt;
import { ref } from 'vue';

const ok = ref(true)


&lt;/script&gt;

&lt;style scoped&gt;

&lt;/style&gt;
</code></pre> <p>Tip</p> <p>v-if 有更高的切换开销，而 v-show 有更高的初始渲染开销。因此，如果需要频繁切换，则使用 v-show 较好；如果在运行时绑定条件很少改变，则 v-if 会更合适</p>

components/Syntax.vue <pre><code>&lt;template&gt;
   &lt;table border="1" style="border-collapse: collapse"&gt;
      &lt;thead&gt;
         &lt;tr&gt;
            &lt;td&gt;序号&lt;/td&gt;
            &lt;td&gt;作者&lt;/td&gt;
            &lt;td&gt;书籍&lt;/td&gt;
         &lt;/tr&gt;
      &lt;/thead&gt;
      &lt;tbody&gt;
         &lt;!-- 循环books.items --&gt;
         &lt;tr v-for="(book, index) in books.items" :key="index"&gt;
            &lt;td&gt;{{ index +1  }}&lt;/td&gt;
            &lt;td&gt;{{ book.author }}&lt;/td&gt;
            &lt;td&gt;{{ book.book_name }}&lt;/td&gt;
         &lt;/tr&gt;
      &lt;/tbody&gt;
   &lt;/table&gt;
   &lt;button @click="changeBooks"&gt;书籍变更&lt;/button&gt;
&lt;/template&gt;

&lt;script setup&gt;
import { reactive } from 'vue';
// 更符合实际使用场景
const books = reactive({
   items:[
   {"author": "罗贯中", "book_name":"三国演义"},
   {"author": "吴承恩", "book_name":"西游记"},
   {"author": "曹雪芹", "book_name":"红楼梦"},
   {"author": "施耐庵", "book_name":"水浒传"},
   ]
})

const changeBooks= ()=&gt; {
   // // 1. 添加元素
   // // 第1个参数: 起始位置：从索引 1 开始添加
   // // 第2个参数: 删除个数：删除 0 个元素
   // // 第3个参数: 要插入的元素
   // books.items.splice(1, 0, {author: "dengyouf", book_name: "Vue从入门到放弃"})

   // // 2. 删除元素,从索引1开始，删除2个元素，也就是删除索引为1 2 一共两个元素
   // books.items.splice(1, 2)

   // 3. 替换元素， 从索引1开始，删除1个元素, 然后插入新值
   books.items.splice(1, 1,  {author: "dengyouf", book_name: "Vue从入门到放弃"})
}
&lt;/script&gt;

&lt;style scoped&gt;

&lt;/style&gt;
</code></pre>
